head.script:
scwin.screenId = "jldstf07341";

///////// 1. 변수 및 선언 영역 /////////

scwin.vID = undefined;

scwin.vScrenID = "ULDSTF07341.gfm";

scwin.vScrenProcTpCd = "";

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.vScrenProcTpCd = undefined;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const parentWin = $c.win.getParent();
        scwin.vID = parentWin.clickID;
        scwin.fn_read_sync();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07341.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_examprn = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsExamprn')) : $c.util.getComponent('dtsExamprn');

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07341.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Save_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Save_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fn_trs();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07341.btn_Save_onclick' }); }
};

/**
 * @method
 * @name scwin.dts_examprn_onloaderror
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.dts_examprn_onloaderror = function () {
    /* sdd-asis-lifecycle:begin dts_examprn_onloaderror — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.fil.alert_error(scwin.dts_examprn);
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.trs_Save_onfail
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.trs_Save_onfail = function () {
    /* sdd-asis-lifecycle:begin trs_Save_onfail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.lc.fn_alertMsg('F');
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.trs_Save_onsuccess
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.trs_Save_onsuccess = function () {
    /* sdd-asis-lifecycle:begin trs_Save_onsuccess — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.lc.fn_alertMsg('S1');
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
 * @name scwin.btn_init_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_init_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_init_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.dts_examprn.setCellData(1, "ACCSS_POSBL_IP_LIST_CONTN", "");
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07341.btn_init_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Close_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Close_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.frame.CloseFrame();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07341.btn_Close_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_script_dts_examprn
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_examprn = async function () {
    $c.util.getComponent("dma_scriptDtsExamprnReq").set("SCREN_ID", "ULDSTF07341.gfm");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, INTEG_USR_ID", unresolved: "query_param:SCREN_PROCES_TP_CD,INTEG_USR_ID" };
    const sbmOptions = {
        id: "tx_script_dts_examprn",
        method: "post",
        action: "/konex/InvstgAssgn.do",
        ref: "dma_scriptDtsExamprnReq",
        target: "dtsExamprn=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_examprn_onloaderror'] === 'function') ? scwin['dts_examprn_onloaderror'] : (typeof scwin['dts_examprn_onfail'] === 'function') ? scwin['dts_examprn_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_examprn_onloadcompleted'] === 'function') ? scwin['dts_examprn_onloadcompleted'] : ((typeof scwin['dts_examprn_onsuccess'] === 'function') ? scwin['dts_examprn_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dtsExamprn'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07341.tx_script_dts_examprn" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.sbm_trs_Save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.sbm_trs_Save = async function () {
    const sbmOptions = {
        id: "sbm_trs_Save",
        method: "post",
        action: "/konex/InvstgAssgn.do",
        ref: "dma_sbmTrs_SaveReq",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['trs_Save_onloaderror'] === 'function') ? scwin['trs_Save_onloaderror'] : (typeof scwin['trs_Save_onfail'] === 'function') ? scwin['trs_Save_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['trs_Save_onloadcompleted'] === 'function') ? scwin['trs_Save_onloadcompleted'] : ((typeof scwin['trs_Save_onsuccess'] === 'function') ? scwin['trs_Save_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('trs_Save'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07341.sbm_trs_Save" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.parentRefresh
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.parentRefresh = function () {
    /* sdd-asis-lifecycle:begin fn_parentRefresh — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fr_fn_list_sync = $c.win.getParent().fn_list_sync;
    fr_fn_list_sync();
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.fn_read_sync = scwin.tx_script_dts_examprn;

scwin.fn_trs = scwin.sbm_trs_Save;
